import { createClient } from '@supabase/supabase-js';
import './style.css';

const KEY = 'sales-manager-ar-v1';
const DEFAULTS = {
  customers: [], invoices: [], collections: [], audit: [], historical: [],
  settings: { commissionRate: 2, monthlyDeduction: 20000, dueSoonDays: 7, currency: 'SAR' },
  counters: {}
};
let db = loadDB(), page = 'dashboard', modal = null, searchText = '', selectedCustomer = null;
let reportYear = new Date().getFullYear(), reportMonth = new Date().getMonth()+1;
let supabase = null, cloudEnabled = false;

function loadDB(){ try { const d=JSON.parse(localStorage.getItem(KEY)||'null'); return d ? {...structuredClone(DEFAULTS),...d,settings:{...DEFAULTS.settings,...d.settings}} : structuredClone(DEFAULTS); } catch { return structuredClone(DEFAULTS); } }
function persist(){ localStorage.setItem(KEY,JSON.stringify(db)); }
function uid(prefix='id'){return prefix+'_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8)}
function today(){return new Date().toISOString().slice(0,10)}
function money(n){return new Intl.NumberFormat('ar-SA',{style:'currency',currency:'SAR',maximumFractionDigits:2}).format(Number(n)||0)}
function num(v){return Number(v)||0}
function fmtDate(s){if(!s)return '—';const d=new Date(s+'T12:00:00');return isNaN(d)?'—':d.toLocaleDateString('ar-SA')}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function customer(id){return db.customers.find(c=>c.id===id)}
function invoice(id){return db.invoices.find(i=>i.id===id)}
function totalCollected(targetType,targetId){return db.collections.filter(c=>c.targetType===targetType&&c.targetId===targetId&&!c.voided).reduce((s,c)=>s+num(c.amount),0)}
function openingBalance(c){return Math.max(0,num(c.openingBalance)-totalCollected('opening',c.id))}
function invoiceBalance(i){return i.type==='cash'?0:Math.max(0,num(i.amount)-totalCollected('invoice',i.id))}
function customerDebt(c){return openingBalance(c)+db.invoices.filter(i=>i.customerId===c.id&&i.type==='credit').reduce((s,i)=>s+invoiceBalance(i),0)}
function customerSales(c){return db.invoices.filter(i=>i.customerId===c.id).reduce((s,i)=>s+num(i.amount),0)+db.historical.filter(h=>h.customerName===c.name).reduce((s,h)=>s+num(h.amount),0)}
function invoiceStatus(i){if(i.type==='cash')return 'نقدية';const bal=invoiceBalance(i);if(bal<=0)return 'مسددة بالكامل';if(totalCollected('invoice',i.id)>0)return 'مسددة جزئيًا';if(i.dueDate&&i.dueDate<today())return 'متأخرة';return 'آجلة'}
function isOverdue(i){return i.type==='credit'&&invoiceBalance(i)>0&&i.dueDate&&i.dueDate<today()}
function daysLate(i){return isOverdue(i)?Math.floor((new Date(today())-new Date(i.dueDate))/(86400000)):0}
function audit(action,entity,id,before,after){db.audit.unshift({id:uid('audit'),at:new Date().toISOString(),action,entity,entityId:id,before:before?structuredClone(before):null,after:after?structuredClone(after):null});persist()}
function notify(message,error=false){const old=document.querySelector('.toast');if(old)old.remove();const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),3500)}
function addInvoice(input){const year=(input.date||today()).slice(0,4);const seq=(db.counters[year]||0)+1;db.counters[year]=seq;const id=uid('inv');const dueDate=input.type==='credit'?addDays(input.date,input.term):'';const item={...input,id,number:`${year}-${String(seq).padStart(3,'0')}`,dueDate,createdAt:new Date().toISOString()};db.invoices.push(item);if(item.type==='cash'){db.collections.push({id:uid('col'),customerId:item.customerId,targetType:'invoice',targetId:id,amount:num(item.amount),date:item.date,method:item.paymentMethod||'نقدي',reference:'',notes:'تحصيل تلقائي لفاتورة نقدية',auto:true,voided:false,createdAt:new Date().toISOString()});}audit('إضافة','فاتورة',id,null,item);persist()}
function addDays(date,days){if(!date)return '';const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+Number(days||0));return d.toISOString().slice(0,10)}
function monthSales(year,month){return db.invoices.filter(i=>i.date?.startsWith(`${year}-${String(month).padStart(2,'0')}`)).reduce((s,i)=>s+num(i.amount),0)+db.historical.filter(h=>h.date?.startsWith(`${year}-${String(month).padStart(2,'0')}`)).reduce((s,h)=>s+num(h.amount),0)}
function yearSales(year){return db.invoices.filter(i=>i.date?.startsWith(String(year))).reduce((s,i)=>s+num(i.amount),0)+db.historical.filter(h=>h.date?.startsWith(String(year))).reduce((s,h)=>s+num(h.amount),0)}
function monthCommission(year,month){const sales=monthSales(year,month), deduction=num(db.settings.monthlyDeduction), base=Math.max(0,sales-deduction);return {sales,deduction,base,commission:base*num(db.settings.commissionRate)/100}}
function yearCommission(year){const sales=yearSales(year),deduction=num(db.settings.monthlyDeduction)*12,base=Math.max(0,sales-deduction);return {sales,deduction,base,commission:base*num(db.settings.commissionRate)/100}}
function allYearOptions(){const years=new Set([new Date().getFullYear(),...db.invoices.map(i=>Number(i.date?.slice(0,4))).filter(Boolean),...db.historical.map(h=>Number(h.date?.slice(0,4))).filter(Boolean)]);return [...years].sort((a,b)=>b-a)}
function badge(status){let cls='gray';if(['نقدية','مسددة بالكامل'].includes(status))cls='green';else if(status==='متأخرة')cls='red';else if(status==='مسددة جزئيًا')cls='orange';else if(status==='آجلة')cls='blue';return `<span class="badge ${cls}">${esc(status)}</span>`}
const navItems=[['dashboard','▦','لوحة التحكم'],['customers','♙','العملاء'],['invoices','▤','الفواتير'],['debts','◷','المديونيات'],['collections','⇄','التحصيلات'],['reports','▥','التقارير'],['import','⇧','استيراد البيانات'],['audit','◉','سجل المراجعة'],['settings','⚙','الإعدادات']];
function render(){const title=navItems.find(n=>n[0]===page)?.[2]||'إدارة المبيعات';document.getElementById('app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">م</div><div><h1>مدار المبيعات</h1><small>إدارة مالية مبسطة</small></div></div><nav class="nav">${navItems.map(([id,icon,label])=>`<button data-page="${id}" class="${page===id?'active':''}"><span class="nav-icon">${icon}</span>${label}</button>`).join('')}</nav><div class="side-note">البيانات محفوظة محليًا على هذا الجهاز. فعّل الربط السحابي من الإعدادات بعد إعداد Supabase لمزامنة الأجهزة.</div></aside><main class="main"><header class="topbar"><div><h2>${title}</h2><p>${new Date().toLocaleDateString('ar-SA',{weekday:'long',year:'numeric',month:'long',day:'numeric'})}</p></div><div class="top-actions"><button class="btn btn-light" data-action="backup">⇩ نسخة احتياطية</button><button class="btn btn-primary" data-action="new-invoice">＋ فاتورة جديدة</button></div></header><section class="content">${renderPage()}</section></main></div>${modal?renderModal():''}`;
 bindEvents(); if(page==='dashboard')drawSalesChart(); }
function stat(label,value,icon,foot=''){return `<div class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function renderDashboard(){const year=reportYear, sales=yearSales(year), cash=db.invoices.filter(i=>i.type==='cash'&&i.date?.startsWith(String(year))).reduce((s,i)=>s+num(i.amount),0),credit=db.invoices.filter(i=>i.type==='credit'&&i.date?.startsWith(String(year))).reduce((s,i)=>s+num(i.amount),0),collected=db.collections.filter(c=>!c.voided&&c.date?.startsWith(String(year))).reduce((s,c)=>s+num(c.amount),0),debt=db.customers.reduce((s,c)=>s+customerDebt(c),0),late=db.invoices.filter(isOverdue).reduce((s,i)=>s+invoiceBalance(i),0),comm=yearCommission(year);
const due=db.invoices.filter(i=>i.type==='credit'&&invoiceBalance(i)>0&&i.dueDate&&i.dueDate>=today()&&i.dueDate<=addDays(today(),num(db.settings.dueSoonDays))).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));
const overdue=db.invoices.filter(isOverdue).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));
const top=[...db.customers].map(c=>({c,s:customerSales(c)})).sort((a,b)=>b.s-a.s).slice(0,5);
return `<div class="page-head"><div><h3>مرحبًا بك في لوحة التحكم</h3><div class="muted">ملخص النشاط المالي والتنبيهات • الأرقام تتحدث تلقائيًا من بيانات النظام</div></div><div class="year-controls"><label class="muted">السنة</label><select id="dash-year">${allYearOptions().map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></div></div>
<div class="cards">${stat('إجمالي المبيعات',money(sales),'↗',`السنة ${year}`)}${stat('المبيعات النقدية',money(cash),'◉','فواتير نقدية')}${stat('المبيعات الآجلة',money(credit),'▤','فواتير آجلة')}${stat('إجمالي التحصيلات',money(collected),'⇄','حسب تاريخ التحصيل')}${stat('المديونية الحالية',money(debt),'◷','أرصدة افتتاحية وفواتير آجلة')}${stat('المديونيات المتأخرة',money(late),'⚠','فواتير تجاوزت الاستحقاق')}${stat('العملاء',db.customers.length,'♙','عميل مسجل')}${stat('العمولات السنوية',money(comm.commission),'٪',`وعاء العمولة: ${money(comm.base)}`)}</div>
<div class="grid-2"><div class="panel"><div class="panel-head"><h4>حركة المبيعات الشهرية</h4><span class="muted">${year}</span></div><div class="chart-wrap"><canvas id="sales-chart"></canvas></div><div class="legend"><span>المبيعات</span><span>الخصم الشهري ${money(db.settings.monthlyDeduction)}</span></div></div><div class="panel"><div class="panel-head"><h4>تنبيهات الاستحقاق</h4><span class="badge ${overdue.length?'red':'green'}">${overdue.length} متأخرة</span></div><div class="alert-list">${overdue.slice(0,4).map(i=>`<div class="alert red"><span class="dot"></span><div><b>${esc(i.number)} — ${esc(customer(i.customerId)?.name||'عميل محذوف')}</b><div>${money(invoiceBalance(i))} • متأخرة ${daysLate(i)} يومًا</div></div></div>`).join('')}${due.slice(0,3).map(i=>`<div class="alert"><span class="dot"></span><div><b>${esc(i.number)} — ${esc(customer(i.customerId)?.name||'')}</b><div>${money(invoiceBalance(i))} • الاستحقاق ${fmtDate(i.dueDate)}</div></div></div>`).join('')}${!overdue.length&&!due.length?'<div class="empty">لا توجد تنبيهات استحقاق حاليًا.</div>':''}</div></div></div>
<div class="grid-2"><div class="panel"><div class="panel-head"><h4>أفضل العملاء حسب المبيعات</h4><button class="btn btn-light btn-small" data-page="customers">عرض العملاء</button></div><div class="bar-list">${top.length?top.map(({c,s})=>`<div class="bar-row"><span>${esc(c.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(2,s/(top[0].s||1)*100)}%"></div></div><b>${money(s)}</b></div>`).join(''):'<div class="empty">أضف عملاء وفواتير لعرض الترتيب.</div>'}</div></div><div class="panel"><div class="panel-head"><h4>ملخص العمولة السنوية</h4><span class="badge blue">${db.settings.commissionRate}%</span></div><div class="bar-list"><div class="bar-row"><span>المبيعات</span><div class="bar-track"><div class="bar-fill" style="width:100%"></div></div><b>${money(comm.sales)}</b></div><div class="bar-row"><span>الخصم السنوي</span><div class="bar-track"><div class="bar-fill" style="width:${Math.min(100,comm.deduction/(comm.sales||1)*100)}%;background:#f59e0b"></div></div><b>${money(comm.deduction)}</b></div><div class="bar-row"><span>وعاء العمولة</span><div class="bar-track"><div class="bar-fill" style="width:${comm.sales?comm.base/comm.sales*100:0}%"></div></div><b>${money(comm.base)}</b></div></div><p class="muted">المعادلة: ${db.settings.commissionRate}% × max(0، المبيعات السنوية − ${money(comm.deduction)}).</p></div></div>
<div class="footer-note">تنبيه: البيانات المحلية محفوظة في المتصفح الحالي. استخدم النسخة الاحتياطية بانتظام، أو أعد إعداد Supabase للمزامنة السحابية.</div>`}
function renderCustomers(){const list=db.customers.filter(c=>(c.name+' '+(c.phone||'')).toLowerCase().includes(searchText.toLowerCase()));return `<div class="page-head"><div><h3>إدارة العملاء</h3><div class="muted">ملفات العملاء والأرصدة الافتتاحية وسجل الحساب</div></div><button class="btn btn-primary" data-action="add-customer">＋ إضافة عميل</button></div><div class="toolbar"><input class="search" id="search" placeholder="ابحث بالاسم أو رقم الهاتف…" value="${esc(searchText)}"/><span class="muted">${list.length} عميل</span></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>العميل</th><th>رقم الهاتف</th><th>إجمالي المبيعات</th><th>الرصيد الافتتاحي المتبقي</th><th>المديونية الحالية</th><th>المتأخر</th><th>الإجراءات</th></tr></thead><tbody>${list.map(c=>`<tr><td><b>${esc(c.name)}</b><div class="muted">${esc(c.address||'')}</div></td><td>${esc(c.phone||'—')}</td><td>${money(customerSales(c))}</td><td>${money(openingBalance(c))}</td><td><b>${money(customerDebt(c))}</b></td><td>${money(db.invoices.filter(i=>i.customerId===c.id&&isOverdue(i)).reduce((s,i)=>s+invoiceBalance(i),0))}</td><td><div class="actions"><button class="icon-btn" data-action="customer-detail" data-id="${c.id}">التفاصيل</button><button class="icon-btn" data-action="edit-customer" data-id="${c.id}">تعديل</button><button class="icon-btn danger" data-action="delete-customer" data-id="${c.id}">حذف</button></div></td></tr>`).join('')||`<tr><td colspan="7" class="empty">لا توجد نتائج. أضف أول عميل للبدء.</td></tr>`}</tbody></table></div></div>`}
function renderInvoices(){const list=db.invoices.filter(i=>{const c=customer(i.customerId);return (i.number+' '+(c?.name||'')).toLowerCase().includes(searchText.toLowerCase())});return `<div class="page-head"><div><h3>الفواتير</h3><div class="muted">ترقيم سنوي تلقائي • النقدية تُحصّل تلقائيًا دون مديونية</div></div><button class="btn btn-primary" data-action="new-invoice">＋ فاتورة جديدة</button></div><div class="toolbar"><input class="search" id="search" placeholder="ابحث برقم الفاتورة أو العميل…" value="${esc(searchText)}"/><button class="btn btn-light" data-action="print">طباعة</button><button class="btn btn-light" data-action="export-invoices">تصدير CSV</button></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>رقم الفاتورة</th><th>العميل</th><th>التاريخ</th><th>النوع</th><th>القيمة</th><th>المحصّل</th><th>المتبقي</th><th>الاستحقاق</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${list.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(i=>`<tr><td><b>${esc(i.number)}</b></td><td>${esc(customer(i.customerId)?.name||'عميل غير موجود')}</td><td>${fmtDate(i.date)}</td><td>${i.type==='cash'?'نقدية':'آجلة'}</td><td>${money(i.amount)}</td><td>${money(i.type==='cash'?i.amount:totalCollected('invoice',i.id))}</td><td>${money(invoiceBalance(i))}</td><td>${fmtDate(i.dueDate)}</td><td>${badge(invoiceStatus(i))}</td><td><div class="actions"><button class="icon-btn" data-action="view-invoice" data-id="${i.id}">عرض</button><button class="icon-btn" data-action="edit-invoice" data-id="${i.id}">تعديل</button><button class="icon-btn danger" data-action="delete-invoice" data-id="${i.id}">حذف</button></div></td></tr>`).join('')||'<tr><td colspan="10" class="empty">لا توجد فواتير حتى الآن.</td></tr>'}</tbody></table></div></div>`}
function renderDebts(){const customers=db.customers.map(c=>({c,debt:customerDebt(c),late:db.invoices.filter(i=>i.customerId===c.id&&isOverdue(i)).reduce((s,i)=>s+invoiceBalance(i),0)})).filter(x=>x.debt>0).sort((a,b)=>b.debt-a.debt);const items=db.invoices.filter(i=>i.type==='credit'&&invoiceBalance(i)>0).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));return `<div class="page-head"><div><h3>المديونيات</h3><div class="muted">الأرصدة الافتتاحية والفواتير الآجلة مطروحة منها التحصيلات المرتبطة فقط</div></div><button class="btn btn-primary" data-action="add-collection">＋ تسجيل تحصيل</button></div><div class="cards">${stat('إجمالي المديونية',money(db.customers.reduce((s,c)=>s+customerDebt(c),0)),'◷')}${stat('مديونية متأخرة',money(items.filter(isOverdue).reduce((s,i)=>s+invoiceBalance(i),0)),'⚠')}${stat('غير متأخرة',money(items.filter(i=>!isOverdue(i)).reduce((s,i)=>s+invoiceBalance(i),0)),'✓')}${stat('عملاء عليهم رصيد',customers.length,'♙')}</div><div class="panel"><h4>أرصدة العملاء المستحقة</h4><div class="table-wrap"><table><thead><tr><th>العميل</th><th>المديونية الحالية</th><th>المتأخر</th><th>عدد الفواتير المفتوحة</th><th>إجراء</th></tr></thead><tbody>${customers.map(({c,debt,late})=>`<tr><td><b>${esc(c.name)}</b></td><td>${money(debt)}</td><td>${money(late)}</td><td>${items.filter(i=>i.customerId===c.id).length}</td><td><button class="icon-btn" data-action="customer-detail" data-id="${c.id}">تفاصيل الحساب</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا توجد مديونيات مستحقة.</td></tr>'}</tbody></table></div></div><div class="panel" style="margin-top:16px"><h4>الفواتير غير المسددة</h4><div class="table-wrap"><table><thead><tr><th>الفاتورة</th><th>العميل</th><th>الاستحقاق</th><th>المتبقي</th><th>أيام التأخير</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.number)}</td><td>${esc(customer(i.customerId)?.name||'')}</td><td>${fmtDate(i.dueDate)}</td><td>${money(invoiceBalance(i))}</td><td>${daysLate(i)||0}</td><td>${badge(invoiceStatus(i))}</td><td><button class="icon-btn" data-action="collect-invoice" data-id="${i.id}">تحصيل</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">لا توجد فواتير مفتوحة.</td></tr>'}</tbody></table></div></div>`}
function renderCollections(){return `<div class="page-head"><div><h3>التحصيلات</h3><div class="muted">كل تحصيل مرتبط برصيد افتتاحي أو فاتورة محددة لمنع الخصم المكرر</div></div><button class="btn btn-primary" data-action="add-collection">＋ تسجيل تحصيل</button></div><div class="toolbar"><button class="btn btn-light" data-action="export-collections">تصدير CSV</button><button class="btn btn-light" data-action="print">طباعة</button></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>العميل</th><th>المرجع المسدد</th><th>المبلغ</th><th>طريقة الدفع</th><th>رقم مرجعي</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>${db.collections.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(c=>{const target=c.targetType==='invoice'?invoice(c.targetId):customer(c.targetId);return `<tr><td>${fmtDate(c.date)}</td><td>${esc(customer(c.customerId)?.name||'')}</td><td>${c.targetType==='invoice'?esc(target?.number||'فاتورة'):('رصيد افتتاحي — '+esc(target?.name||''))}</td><td>${money(c.amount)}</td><td>${esc(c.method||'—')}</td><td>${esc(c.reference||'—')}</td><td>${c.voided?badge('ملغى'):badge('مسجل')}</td><td><div class="actions"><button class="icon-btn" data-action="edit-collection" data-id="${c.id}" ${c.auto?'disabled title="تحصيل نقدي تلقائي"':''}>تعديل</button><button class="icon-btn danger" data-action="void-collection" data-id="${c.id}" ${c.auto?'disabled title="لا يمكن إلغاء التحصيل التلقائي منفردًا"':''}>إلغاء</button></div></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">لا توجد تحصيلات مسجلة.</td></tr>'}</tbody></table></div></div>`}
function renderReports(){const mc=monthCommission(reportYear,reportMonth),yc=yearCommission(reportYear);const years=allYearOptions();return `<div class="page-head"><div><h3>التقارير والعمولات</h3><div class="muted">اختر الفترة لعرض تقارير المبيعات والوعاء والعمولات</div></div><button class="btn btn-light" data-action="print">طباعة / حفظ PDF</button></div><div class="toolbar"><div class="field"><label>السنة</label><select id="report-year">${years.map(y=>`<option value="${y}" ${y===reportYear?'selected':''}>${y}</option>`).join('')}</select></div><div class="field"><label>الشهر</label><select id="report-month">${Array.from({length:12},(_,i)=>i+1).map(m=>`<option value="${m}" ${m===reportMonth?'selected':''}>${new Date(2024,m-1,1).toLocaleDateString('ar-SA',{month:'long'})}</option>`).join('')}</select></div><button class="btn btn-light" data-action="export-report">تصدير التقرير CSV</button></div><div class="grid-2"><div class="panel"><h4>تقرير الشهر</h4><div class="cards" style="grid-template-columns:repeat(2,minmax(0,1fr))">${stat('مبيعات الشهر',money(mc.sales),'↗')}${stat('خصم الشهر',money(mc.deduction),'−')}${stat('وعاء العمولة',money(mc.base),'∑')}${stat('العمولة الشهرية',money(mc.commission),'٪')}</div><div class="notice">المعادلة الشهرية المعروضة: ${db.settings.commissionRate}% × max(0، مبيعات الشهر − ${money(mc.deduction)}). لا تُنتج عمولة سالبة إذا كانت المبيعات أقل من الخصم.</div></div><div class="panel"><h4>تقرير السنة</h4><div class="cards" style="grid-template-columns:repeat(2,minmax(0,1fr))">${stat('مبيعات السنة',money(yc.sales),'↗')}${stat('خصم السنة مرة واحدة',money(yc.deduction),'−')}${stat('وعاء العمولة السنوي',money(yc.base),'∑')}${stat('العمولة السنوية',money(yc.commission),'٪')}</div><div class="notice">المعادلة السنوية: ${db.settings.commissionRate}% × max(0، إجمالي مبيعات السنة − (12 × ${money(db.settings.monthlyDeduction)})). هذه النتيجة مستقلة ولا تجمع العمولات الشهرية ثم تخصم الخصم مرة أخرى.</div></div></div><div class="panel"><h4>مقارنة المبيعات السنوية</h4><div class="bar-list">${years.map(y=>`<div class="bar-row"><span>${y}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(1,yearSales(y)/(Math.max(...years.map(yearSales),1))*100)}%"></div></div><b>${money(yearSales(y))}</b></div>`).join('')||'<div class="empty">لا توجد بيانات تاريخية بعد.</div>'}</div></div><div class="panel" style="margin-top:16px"><h4>أفضل العملاء حسب إجمالي المبيعات</h4><div class="table-wrap"><table><thead><tr><th>الترتيب</th><th>العميل</th><th>المبيعات</th><th>المديونية الحالية</th></tr></thead><tbody>${db.customers.map(c=>({c,s:customerSales(c)})).sort((a,b)=>b.s-a.s).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.c.name)}</td><td>${money(x.s)}</td><td>${money(customerDebt(x.c))}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">لا توجد بيانات.</td></tr>'}</tbody></table></div></div>`}
function renderImport(){return `<div class="page-head"><div><h3>استيراد البيانات التاريخية</h3><div class="muted">استورد ملفات CSV أو Excel، راجع الصفوف والتكرارات قبل الاعتماد</div></div></div><div class="notice">البيانات المستوردة تحفظ كسجلات تاريخية للتحليل فقط ولا تنشئ مديونيات. الصفوف التي لا تحتوي على تاريخ تبقى في قائمة مراجعة مستقلة. لا يتم حذف الصفوف المتشابهة تلقائيًا.</div><div class="panel"><h4>اختيار ملف</h4><div class="field"><label>ملف Excel (.xlsx / .xls) أو CSV</label><input id="import-file" type="file" accept=".xlsx,.xls,.csv"/></div><p class="muted">تتم قراءة Excel عبر مكتبة SheetJS من CDN عند توفر الإنترنت. إذا لم تعمل المكتبة، احفظ الملف بصيغة CSV UTF-8 ثم استورده.</p><div id="import-preview"></div></div><div class="panel" style="margin-top:16px"><div class="panel-head"><h4>السجلات التاريخية المعتمدة</h4><span class="badge blue">${db.historical.length} سجل</span></div><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>العميل</th><th>رقم الفاتورة الأصلي</th><th>المبلغ</th><th>المصدر</th></tr></thead><tbody>${db.historical.slice(-100).reverse().map(h=>`<tr><td>${fmtDate(h.date)}</td><td>${esc(h.customerName||'—')}</td><td>${esc(h.originalNumber||'—')}</td><td>${money(h.amount)}</td><td>${esc(h.source||'استيراد')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">لم يتم اعتماد سجلات تاريخية بعد.</td></tr>'}</tbody></table></div></div>`}
function renderAudit(){return `<div class="page-head"><div><h3>سجل المراجعة</h3><div class="muted">سجل زمني للعمليات المهمة والتعديلات</div></div><button class="btn btn-light" data-action="export-audit">تصدير السجل</button></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>التاريخ والوقت</th><th>العملية</th><th>النوع</th><th>المعرف</th><th>ملخص</th></tr></thead><tbody>${db.audit.map(a=>`<tr><td>${new Date(a.at).toLocaleString('ar-SA')}</td><td>${esc(a.action)}</td><td>${esc(a.entity)}</td><td>${esc(a.entityId)}</td><td>${esc(JSON.stringify(a.after||a.before||{}).slice(0,180))}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا توجد عمليات مسجلة بعد.</td></tr>'}</tbody></table></div></div>`}
function renderSettings(){return `<div class="page-head"><div><h3>الإعدادات</h3><div class="muted">ضبط سياسة العمولات والتذكيرات والربط السحابي</div></div></div><div class="grid-2"><div class="panel"><h4>إعدادات العمولات والتنبيهات</h4><form id="settings-form" class="form-grid"><div class="field"><label>نسبة العمولة (%)</label><input name="commissionRate" type="number" min="0" max="100" step=".01" value="${db.settings.commissionRate}" required/></div><div class="field"><label>خصم الشركة الشهري (ريال)</label><input name="monthlyDeduction" type="number" min="0" step=".01" value="${db.settings.monthlyDeduction}" required/></div><div class="field"><label>التنبيه قبل الاستحقاق (أيام)</label><input name="dueSoonDays" type="number" min="0" max="90" step="1" value="${db.settings.dueSoonDays}" required/></div><div class="field"><label>العملة</label><input value="الريال السعودي (SAR)" disabled/></div><div class="span-2"><button class="btn btn-primary" type="submit">حفظ الإعدادات</button></div></form><div class="notice" style="margin-top:16px">سياسة العمولة: الشهرية = النسبة × max(0، مبيعات الشهر − الخصم الشهري). السنوية = النسبة × max(0، مبيعات السنة − 12 × الخصم الشهري). هذه سياسة واضحة قابلة للتعديل في الإصدارات القادمة.</div></div><div class="panel"><h4>النسخ الاحتياطي والبيانات</h4><p class="muted">نزّل نسخة JSON تشمل العملاء والفواتير والتحصيلات والإعدادات وسجل المراجعة والبيانات التاريخية.</p><div class="toolbar"><button class="btn btn-primary" data-action="backup">تنزيل نسخة احتياطية</button><label class="btn btn-light" for="restore-file">استعادة نسخة JSON</label><input id="restore-file" type="file" accept=".json,application/json" hidden/></div><div class="notice danger-notice">الاستعادة تستبدل البيانات الحالية بالكامل. أنشئ نسخة احتياطية أولًا.</div><hr style="border:0;border-top:1px solid #edf1f4;margin:20px 0"/><h4>الربط السحابي (Supabase)</h4><div class="notice">أدخل بيانات مشروع Supabase من ملف .env.local ثم أعد تشغيل التطبيق. المفتاح المستخدم في المتصفح يجب أن يكون anon/publishable فقط مع تفعيل RLS. لا تضع service_role key هنا.</div><div class="muted">حالة الاتصال: ${cloudEnabled?'<span class="badge orange">الإعداد موجود — المزامنة غير مفعّلة</span>':'<span class="badge orange">محلي فقط — غير متصل</span>'}</div><p class="muted">ملف إعداد نموذجي: <code>.env.example</code>، وتعريف الجداول والسياسات في <code>supabase/schema.sql</code>.</p></div></div>`}
function renderCustomerDetail(){const c=customer(selectedCustomer);if(!c)return '<div class="empty">العميل غير موجود.</div>';const invs=db.invoices.filter(i=>i.customerId===c.id), cols=db.collections.filter(x=>x.customerId===c.id);return `<div class="page-head"><div><h3>${esc(c.name)}</h3><div class="muted">${esc(c.phone||'لا يوجد هاتف')} • ${esc(c.address||'لا يوجد عنوان')}</div></div><div class="actions"><button class="btn btn-light" data-action="edit-customer" data-id="${c.id}">تعديل العميل</button><button class="btn btn-primary" data-action="add-collection" data-id="${c.id}">＋ تحصيل</button><button class="btn btn-light" data-page="customers">رجوع</button></div></div><div class="customer-detail"><div class="mini-stat"><small>إجمالي المبيعات</small><strong>${money(customerSales(c))}</strong></div><div class="mini-stat"><small>الرصيد الافتتاحي المتبقي</small><strong>${money(openingBalance(c))}</strong></div><div class="mini-stat"><small>المديونية الحالية</small><strong>${money(customerDebt(c))}</strong></div></div><div class="panel"><h4>الفواتير</h4><div class="table-wrap"><table><thead><tr><th>الرقم</th><th>التاريخ</th><th>القيمة</th><th>المتبقي</th><th>الحالة</th></tr></thead><tbody>${invs.map(i=>`<tr><td>${esc(i.number)}</td><td>${fmtDate(i.date)}</td><td>${money(i.amount)}</td><td>${money(invoiceBalance(i))}</td><td>${badge(invoiceStatus(i))}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا توجد فواتير تشغيلية.</td></tr>'}</tbody></table></div></div><div class="panel" style="margin-top:16px"><h4>سجل التحصيلات</h4><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>المرجع</th><th>المبلغ</th><th>الطريقة</th><th>الحالة</th></tr></thead><tbody>${cols.map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${x.targetType==='invoice'?esc(invoice(x.targetId)?.number||'فاتورة'): 'الرصيد الافتتاحي'}</td><td>${money(x.amount)}</td><td>${esc(x.method||'—')}</td><td>${x.voided?badge('ملغى'):badge('مسجل')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا توجد تحصيلات.</td></tr>'}</tbody></table></div></div><div class="panel" style="margin-top:16px"><h4>ملاحظات</h4><p>${esc(c.notes||'لا توجد ملاحظات.')}</p></div>`}
function renderPage(){if(page==='dashboard')return renderDashboard();if(page==='customers')return selectedCustomer?renderCustomerDetail():renderCustomers();if(page==='invoices')return renderInvoices();if(page==='debts')return renderDebts();if(page==='collections')return renderCollections();if(page==='reports')return renderReports();if(page==='import')return renderImport();if(page==='audit')return renderAudit();if(page==='settings')return renderSettings();return renderDashboard()}
function renderModal(){if(!modal)return '';const m=modal;let title='',body='';
if(m.type==='customer'){const c=m.id?customer(m.id):{};title=m.id?'تعديل بيانات العميل':'إضافة عميل جديد';body=`<form id="customer-form" class="form-grid"><div class="field"><label>اسم العميل *</label><input name="name" required maxlength="150" value="${esc(c.name||'')}"/></div><div class="field"><label>رقم الهاتف</label><input name="phone" maxlength="40" value="${esc(c.phone||'')}"/></div><div class="field span-2"><label>العنوان</label><input name="address" maxlength="250" value="${esc(c.address||'')}"/></div><div class="field"><label>الرصيد الافتتاحي المستحق (ريال)</label><input name="openingBalance" type="number" min="0" step=".01" required value="${c.openingBalance??0}"/></div><div class="field span-2"><label>ملاحظات</label><textarea name="notes">${esc(c.notes||'')}</textarea></div><div class="span-2 muted">الرصيد الافتتاحي لا ينشئ فاتورة تاريخية، ويمكن تسجيل تحصيل مرتبط به من صفحة التحصيلات.</div><div class="span-2 modal-actions"><button class="btn btn-primary" type="submit">حفظ العميل</button><button class="btn btn-light" type="button" data-action="close-modal">إلغاء</button></div></form>`}
if(m.type==='invoice'){const i=m.id?invoice(m.id):{};title=m.id?'تعديل الفاتورة':'فاتورة جديدة';body=`<form id="invoice-form" class="form-grid"><div class="field span-2"><label>العميل *</label><select name="customerId" required><option value="">اختر العميل</option>${db.customers.map(c=>`<option value="${c.id}" ${c.id===i.customerId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>تاريخ الفاتورة *</label><input name="date" type="date" required value="${i.date||today()}"/></div><div class="field"><label>قيمة الفاتورة (ريال) *</label><input name="amount" type="number" min=".01" step=".01" required value="${i.amount??''}"/></div><div class="field"><label>نوع الفاتورة *</label><select name="type" id="invoice-type"><option value="cash" ${(i.type||'credit')==='cash'?'selected':''}>نقدية</option><option value="credit" ${(i.type||'credit')==='credit'?'selected':''}>آجلة</option></select></div><div class="field"><label>طريقة الدفع</label><select name="paymentMethod"><option>نقدي</option><option ${i.paymentMethod==='تحويل بنكي'?'selected':''}>تحويل بنكي</option><option ${i.paymentMethod==='شبكة'?'selected':''}>شبكة</option><option ${i.paymentMethod==='أخرى'?'selected':''}>أخرى</option></select></div><div class="field" id="term-field"><label>مدة الاستحقاق</label><select name="term"><option value="30" ${Number(i.term||30)===30?'selected':''}>30 يومًا</option><option value="45" ${Number(i.term)===45?'selected':''}>45 يومًا</option><option value="60" ${Number(i.term)===60?'selected':''}>60 يومًا</option></select></div><div class="field span-2"><label>ملاحظات</label><textarea name="notes">${esc(i.notes||'')}</textarea></div><div class="span-2 notice">رقم الفاتورة يُنشأ تلقائيًا حسب سنة الفاتورة. عند إنشاء فاتورة نقدية يسجل النظام تحصيلًا تلقائيًا كاملًا. تعديل فاتورة لها تحصيلات غير تلقائية ممنوع لتجنب فساد الأرصدة.</div><div class="span-2 modal-actions"><button class="btn btn-primary" type="submit">حفظ الفاتورة</button><button class="btn btn-light" type="button" data-action="close-modal">إلغاء</button></div></form>`}
if(m.type==='collection'){const c=m.id?db.collections.find(x=>x.id===m.id):{};const presetCustomer=m.customerId||c.customerId||'';const targets=availableTargets(presetCustomer);title=m.id?'تعديل التحصيل':'تسجيل تحصيل';body=`<form id="collection-form" class="form-grid"><div class="field span-2"><label>العميل *</label><select name="customerId" id="col-customer" required><option value="">اختر العميل</option>${db.customers.map(x=>`<option value="${x.id}" ${x.id===presetCustomer?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field span-2"><label>الرصيد أو الفاتورة المراد سدادها *</label><select name="targetKey" id="col-target" required><option value="">اختر الرصيد</option>${targets.map(t=>`<option value="${t.key}" ${c.targetType===t.type&&c.targetId===t.id?'selected':''}>${esc(t.label)} — متبقي ${money(t.balance)}</option>`).join('')}</select></div><div class="field"><label>مبلغ التحصيل (ريال) *</label><input name="amount" type="number" min=".01" step=".01" required value="${c.amount??''}"/></div><div class="field"><label>تاريخ التحصيل *</label><input name="date" type="date" required value="${c.date||today()}"/></div><div class="field"><label>طريقة الدفع</label><select name="method"><option ${c.method==='نقدي'?'selected':''}>نقدي</option><option ${c.method==='تحويل بنكي'?'selected':''}>تحويل بنكي</option><option ${c.method==='شبكة'?'selected':''}>شبكة</option><option ${c.method==='شيك'?'selected':''}>شيك</option><option ${c.method==='أخرى'?'selected':''}>أخرى</option></select></div><div class="field"><label>رقم مرجعي</label><input name="reference" value="${esc(c.reference||'')}"/></div><div class="field span-2"><label>ملاحظات</label><textarea name="notes">${esc(c.notes||'')}</textarea></div><div class="span-2 modal-actions"><button class="btn btn-primary" type="submit">حفظ التحصيل</button><button class="btn btn-light" type="button" data-action="close-modal">إلغاء</button></div></form>`}
if(m.type==='view-invoice'){const i=invoice(m.id);title='تفاصيل الفاتورة';body=i?`<div class="customer-detail"><div class="mini-stat"><small>رقم الفاتورة</small><strong>${esc(i.number)}</strong></div><div class="mini-stat"><small>القيمة</small><strong>${money(i.amount)}</strong></div><div class="mini-stat"><small>المتبقي</small><strong>${money(invoiceBalance(i))}</strong></div></div><p>العميل: ${esc(customer(i.customerId)?.name||'')}</p><p>التاريخ: ${fmtDate(i.date)} • الاستحقاق: ${fmtDate(i.dueDate)}</p><p>الحالة: ${badge(invoiceStatus(i))}</p><p>ملاحظات: ${esc(i.notes||'—')}</p><button class="btn btn-light" data-action="print">طباعة</button><button class="btn btn-primary" data-action="close-modal">إغلاق</button>`:'فاتورة غير موجودة'}
return `<div class="modal-backdrop" data-action="backdrop"><div class="modal" role="dialog" aria-modal="true"><h3>${title}</h3>${body}</div></div>`}
function availableTargets(customerId){const c=customer(customerId);if(!c)return [];const arr=[];const ob=openingBalance(c);if(ob>0)arr.push({type:'opening',id:c.id,key:`opening:${c.id}`,label:'الرصيد الافتتاحي',balance:ob});db.invoices.filter(i=>i.customerId===c.id&&i.type==='credit'&&invoiceBalance(i)>0).forEach(i=>arr.push({type:'invoice',id:i.id,key:`invoice:${i.id}`,label:`فاتورة ${i.number}`,balance:invoiceBalance(i)}));return arr}
function bindEvents(){document.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',()=>{page=el.dataset.page;searchText='';if(page!=='customers')selectedCustomer=null;modal=null;render()}));document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',e=>{const action=el.dataset.action;if(action==='backdrop'&&e.target!==el)return;handleAction(action,el.dataset.id,el)}));
const search=document.getElementById('search');if(search)search.addEventListener('input',()=>{searchText=search.value;const pos=search.selectionStart;render();const next=document.getElementById('search');if(next){next.focus();next.setSelectionRange(pos,pos)}});
const year=document.getElementById('dash-year');if(year)year.addEventListener('change',()=>{reportYear=Number(year.value);render()});
const ry=document.getElementById('report-year'),rm=document.getElementById('report-month');if(ry)ry.addEventListener('change',()=>{reportYear=Number(ry.value);render()});if(rm)rm.addEventListener('change',()=>{reportMonth=Number(rm.value);render()});
const sf=document.getElementById('settings-form');if(sf)sf.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(sf);const before=structuredClone(db.settings);db.settings={...db.settings,commissionRate:Number(f.get('commissionRate')),monthlyDeduction:Number(f.get('monthlyDeduction')),dueSoonDays:Number(f.get('dueSoonDays'))};audit('تعديل','الإعدادات','settings',before,db.settings);persist();notify('تم حفظ الإعدادات');render()});
const cf=document.getElementById('customer-form');if(cf)cf.addEventListener('submit',e=>{e.preventDefault();saveCustomer(new FormData(cf))});
const inf=document.getElementById('invoice-form');if(inf){const type=document.getElementById('invoice-type');type.addEventListener('change',()=>document.getElementById('term-field').style.display=type.value==='credit'?'grid':'none');document.getElementById('term-field').style.display=type.value==='credit'?'grid':'none';inf.addEventListener('submit',e=>{e.preventDefault();saveInvoice(new FormData(inf))})}
const colf=document.getElementById('collection-form');if(colf){document.getElementById('col-customer').addEventListener('change',()=>{const cid=document.getElementById('col-customer').value;const target=document.getElementById('col-target');target.innerHTML='<option value="">اختر الرصيد</option>'+availableTargets(cid).map(t=>`<option value="${t.key}">${esc(t.label)} — متبقي ${money(t.balance)}</option>`).join('')});colf.addEventListener('submit',e=>{e.preventDefault();saveCollection(new FormData(colf))})}
const file=document.getElementById('import-file');if(file)file.addEventListener('change',e=>readImport(e.target.files[0]));
const restore=document.getElementById('restore-file');if(restore)restore.addEventListener('change',e=>restoreBackup(e.target.files[0]));
}
function handleAction(action,id,el){switch(action){
case 'add-customer':modal={type:'customer'};render();break;
case 'edit-customer':modal={type:'customer',id};render();break;
case 'delete-customer':{const c=customer(id);if(!c)return;if(db.invoices.some(i=>i.customerId===id)||db.collections.some(x=>x.customerId===id)){notify('لا يمكن حذف عميل لديه فواتير أو تحصيلات؛ للحفاظ على السجل المالي.',true);return}if(confirm(`هل تريد حذف العميل "${c.name}"؟`)){db.customers=db.customers.filter(x=>x.id!==id);audit('حذف','عميل',id,c,null);persist();notify('تم حذف العميل');render()}break}
case 'customer-detail':selectedCustomer=id;page='customers';modal=null;render();break;
case 'new-invoice':case 'edit-invoice':if(!db.customers.length){notify('أضف عميلًا أولًا قبل إنشاء فاتورة.',true);return}if(action==='edit-invoice'){const i=invoice(id);if(db.collections.some(c=>c.targetType==='invoice'&&c.targetId===id&&!c.voided&&!c.auto)){notify('لا يمكن تعديل فاتورة عليها تحصيلات يدوية. ألغِ التحصيل المرتبط أولًا.',true);return}}modal={type:'invoice',id:action==='edit-invoice'?id:null};render();break;
case 'delete-invoice':{const i=invoice(id);if(!i)return;if(!confirm(`حذف الفاتورة ${i.number}؟ سيتم حذف التحصيل التلقائي المرتبط بها.`))return;const before=structuredClone(i);db.invoices=db.invoices.filter(x=>x.id!==id);db.collections=db.collections.filter(c=>!(c.targetType==='invoice'&&c.targetId===id&&c.auto));audit('حذف','فاتورة',id,before,null);persist();notify('تم حذف الفاتورة');render();break}
case 'view-invoice':modal={type:'view-invoice',id};render();break;
case 'add-collection':case 'collect-invoice':{let cid=id&&invoice(id)?invoice(id).customerId:(id&&customer(id)?id:'');modal={type:'collection',customerId:cid};render();if(action==='collect-invoice'){const target=document.getElementById('col-target');if(target)target.value=`invoice:${id}`}break}
case 'edit-collection':modal={type:'collection',id};render();break;
case 'void-collection':{const c=db.collections.find(x=>x.id===id);if(!c||c.auto)return;if(!confirm('إلغاء هذا التحصيل؟ سيعاد احتساب الرصيد المستحق، وسيتم تسجيل العملية في سجل المراجعة.'))return;const before=structuredClone(c);c.voided=true;audit('إلغاء','تحصيل',id,before,c);persist();notify('تم إلغاء التحصيل وإعادة احتساب الرصيد');render();break}
case 'close-modal':modal=null;render();break;
case 'print':window.print();break;
case 'backup':download('sales-manager-backup-'+today()+'.json',JSON.stringify(db,null,2),'application/json');notify('تم تجهيز النسخة الاحتياطية');break;
case 'export-invoices':exportCSV(db.invoices.map(i=>({'رقم الفاتورة':i.number,'العميل':customer(i.customerId)?.name||'','التاريخ':i.date,'النوع':i.type==='cash'?'نقدية':'آجلة','المبلغ':i.amount,'المحصّل':i.type==='cash'?i.amount:totalCollected('invoice',i.id),'المتبقي':invoiceBalance(i),'الاستحقاق':i.dueDate,'الحالة':invoiceStatus(i)})),'invoices.csv');break;
case 'export-collections':exportCSV(db.collections.map(c=>({'التاريخ':c.date,'العميل':customer(c.customerId)?.name||'','المرجع':c.targetType==='invoice'?invoice(c.targetId)?.number||'':'الرصيد الافتتاحي','المبلغ':c.amount,'الطريقة':c.method,'المرجع البنكي':c.reference,'ملغى':c.voided?'نعم':'لا'})),'collections.csv');break;
case 'export-audit':download('audit-log.json',JSON.stringify(db.audit,null,2),'application/json');break;
case 'export-report':exportCSV([{الفترة:'شهري',السنة:reportYear,الشهر:reportMonth,المبيعات:monthCommission(reportYear,reportMonth).sales,الخصم:monthCommission(reportYear,reportMonth).deduction,وعاء_العمولة:monthCommission(reportYear,reportMonth).base,العمولة:monthCommission(reportYear,reportMonth).commission},{الفترة:'سنوي',السنة:reportYear,المبيعات:yearCommission(reportYear).sales,الخصم:yearCommission(reportYear).deduction,وعاء_العمولة:yearCommission(reportYear).base,العمولة:yearCommission(reportYear).commission}],'commission-report.csv');break;
case 'restore-file':document.getElementById('restore-file')?.click();break;
}}
function saveCustomer(f){const id=modal.id,name=String(f.get('name')||'').trim(),phone=String(f.get('phone')||'').trim(),balance=Number(f.get('openingBalance'));if(!name||!Number.isFinite(balance)||balance<0){notify('تحقق من الاسم والرصيد الافتتاحي.',true);return}const before=id?structuredClone(customer(id)):null;const item={id:id||uid('cus'),name,phone,address:String(f.get('address')||'').trim(),openingBalance:balance,notes:String(f.get('notes')||'').trim(),updatedAt:new Date().toISOString()};if(id){db.customers=db.customers.map(c=>c.id===id?item:c);audit('تعديل','عميل',id,before,item)}else{db.customers.push(item);audit('إضافة','عميل',item.id,null,item)}persist();modal=null;notify('تم حفظ بيانات العميل');render()}
function saveInvoice(f){const id=modal.id,customerId=f.get('customerId'),date=f.get('date'),amount=Number(f.get('amount')),type=f.get('type'),term=Number(f.get('term'));if(!customer(customerId)||!date||!Number.isFinite(amount)||amount<=0){notify('تحقق من العميل والتاريخ والمبلغ.',true);return}if(type==='credit'&&![30,45,60].includes(term)){notify('مدة الاستحقاق يجب أن تكون 30 أو 45 أو 60 يومًا.',true);return}const input={customerId,date,amount,type,term:type==='credit'?term:0,paymentMethod:String(f.get('paymentMethod')||'نقدي'),notes:String(f.get('notes')||'').trim()};if(id){const old=invoice(id);const before=structuredClone(old);Object.assign(old,input,{dueDate:type==='credit'?addDays(date,term):''});if(type==='cash'){let autoCol=db.collections.find(c=>c.targetType==='invoice'&&c.targetId===id&&c.auto);if(!autoCol){autoCol={id:uid('col'),customerId,targetType:'invoice',targetId:id,amount,date,method:input.paymentMethod,notes:'تحصيل تلقائي لفاتورة نقدية',auto:true,voided:false};db.collections.push(autoCol)}else Object.assign(autoCol,{customerId,amount,date,method:input.paymentMethod,voided:false})}if(type==='credit')db.collections=db.collections.filter(c=>!(c.targetType==='invoice'&&c.targetId===id&&c.auto));audit('تعديل','فاتورة',id,before,old)}else addInvoice(input);persist();modal=null;notify('تم حفظ الفاتورة');render()}
function saveCollection(f){const id=modal.id,cid=f.get('customerId'),key=f.get('targetKey'),amount=Number(f.get('amount')),date=f.get('date');if(!customer(cid)||!key||!Number.isFinite(amount)||amount<=0||!date){notify('تحقق من بيانات التحصيل.',true);return}const [targetType,targetId]=key.split(':');if(targetType==='invoice'&&invoice(targetId)?.customerId!==cid||targetType==='opening'&&targetId!==cid){notify('الرصيد المختار لا يتبع العميل المحدد.',true);return}const current=db.collections.find(c=>c.id===id);const targets=availableTargets(cid);let balance=targets.find(t=>t.key===key)?.balance||0;if(current&&!current.voided&&current.targetType===targetType&&current.targetId===targetId)balance+=num(current.amount);if(amount>balance+0.00001){notify(`المبلغ أكبر من الرصيد المتبقي (${money(balance)}).`,true);return}const item={id:id||uid('col'),customerId:cid,targetType,targetId,amount,date,method:String(f.get('method')||'نقدي'),reference:String(f.get('reference')||'').trim(),notes:String(f.get('notes')||'').trim(),auto:false,voided:false,createdAt:current?.createdAt||new Date().toISOString()};if(current){const before=structuredClone(current);Object.assign(current,item);audit('تعديل','تحصيل',id,before,current)}else{db.collections.push(item);audit('إضافة','تحصيل',item.id,null,item)}persist();modal=null;notify('تم حفظ التحصيل وإعادة احتساب الرصيد');render()}
function download(name,data,type){const blob=new Blob([data],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function exportCSV(rows,name){if(!rows.length){notify('لا توجد بيانات للتصدير.',true);return}const headers=[...new Set(rows.flatMap(r=>Object.keys(r)))];const csv='\ufeff'+[headers,...rows.map(r=>headers.map(h=>r[h]??''))].map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');download(name,csv,'text/csv;charset=utf-8');notify('تم تصدير الملف بصيغة CSV المتوافقة مع Excel')}
function restoreBackup(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result);if(!parsed.customers||!parsed.invoices||!parsed.collections)throw Error('invalid');if(!confirm('سيتم استبدال جميع البيانات الحالية. هل تريد المتابعة؟'))return;db={...structuredClone(DEFAULTS),...parsed,settings:{...DEFAULTS.settings,...parsed.settings}};persist();audit('استعادة','نسخة احتياطية','restore',null,{customers:db.customers.length,invoices:db.invoices.length});persist();notify('تمت استعادة النسخة الاحتياطية');render()}catch{notify('ملف النسخة الاحتياطية غير صالح.',true)}};reader.readAsText(file)}
function parseCSV(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'&&quoted&&text[i+1]==='"'){field+='"';i++}else if(ch==='"')quoted=!quoted;else if(ch===','&&!quoted){row.push(field);field=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()))rows.push(row);row=[];field=''}else field+=ch}if(field||row.length){row.push(field);rows.push(row)}return rows}
function normalizeRow(row,headers){const get=(names)=>{const idx=headers.findIndex(h=>names.some(n=>String(h||'').toLowerCase().replace(/\s/g,'').includes(n)));return idx>=0?row[idx]:''};const rawDate=get(['date','التاريخ','تاريخالفاتورة','invoice date']);let date='';if(rawDate instanceof Date)date=rawDate.toISOString().slice(0,10);else if(typeof rawDate==='number'&&rawDate>20000){date=new Date(Date.UTC(1899,11,30)+rawDate*86400000).toISOString().slice(0,10)}else{const s=String(rawDate||'').trim();if(/^\d{4}-\d{1,2}-\d{1,2}/.test(s))date=s.slice(0,10);else{const m=s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);if(m)date=`${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`}}const customerName=String(get(['customer','client','العميل','اسم العميل','اسم العميل'])||'').trim();const amountRaw=get(['amount','total','sales','المبلغ','القيمة','الإجمالي','اجمالي']);const amount=Number(String(amountRaw||'').replace(/[,\sر.س]/g,''))||0;const originalNumber=String(get(['invoice no','invoice number','رقم الفاتورة','الفاتورة'])||'').trim();return {date,customerName,amount,originalNumber,source:'استيراد '+(document.getElementById('import-file')?.files?.[0]?.name||'ملف')}}
async function readImport(file){if(!file)return;const preview=document.getElementById('import-preview');preview.innerHTML='<p class="muted">جارٍ قراءة الملف…</p>';try{let rows;if(file.name.toLowerCase().endsWith('.csv')){rows=parseCSV(await file.text())}else{if(!window.XLSX){await loadSheetJS()}const data=await file.arrayBuffer();const wb=window.XLSX.read(data,{type:'array',cellDates:true});rows=window.XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:''})}if(rows.length<2)throw Error('لا توجد صفوف بيانات');const headers=rows[0];const parsed=rows.slice(1).map(r=>normalizeRow(r,headers));const noDate=parsed.filter(r=>!r.date),valid=parsed.filter(r=>r.date);const duplicate=valid.map((r,i)=>({...r,idx:i})).filter((r,i,a)=>a.findIndex(x=>x.date===r.date&&x.customerName===r.customerName&&x.amount===r.amount&&x.originalNumber===r.originalNumber)!==i);window.__importPreview={valid,noDate,duplicates:duplicate,fileName:file.name};preview.innerHTML=`<div class="customer-detail"><div class="mini-stat"><small>صفوف قابلة للاستيراد</small><strong>${valid.length}</strong></div><div class="mini-stat"><small>بدون تاريخ (مراجعة)</small><strong>${noDate.length}</strong></div><div class="mini-stat"><small>تكرارات محتملة</small><strong>${duplicate.length}</strong></div></div><div class="notice danger-notice">التكرارات المحتملة لا تُحذف تلقائيًا. راجع المعاينة قبل اعتماد جميع الصفوف.</div><h4>معاينة أول 15 صفًا</h4><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>العميل</th><th>رقم الفاتورة</th><th>المبلغ</th><th>ملاحظة</th></tr></thead><tbody>${parsed.slice(0,15).map(r=>`<tr><td>${fmtDate(r.date)}</td><td>${esc(r.customerName||'—')}</td><td>${esc(r.originalNumber||'—')}</td><td>${money(r.amount)}</td><td>${!r.date?badge('بدون تاريخ'):duplicate.some(d=>d.date===r.date&&d.customerName===r.customerName&&d.amount===r.amount&&d.originalNumber===r.originalNumber)?badge('تكرار محتمل'):''}</td></tr>`).join('')}</tbody></table></div><h4 style="margin-top:18px">صفوف بلا تاريخ</h4><div class="table-wrap"><table><thead><tr><th>العميل</th><th>رقم الفاتورة</th><th>المبلغ</th></tr></thead><tbody>${noDate.slice(0,50).map(r=>`<tr><td>${esc(r.customerName||'—')}</td><td>${esc(r.originalNumber||'—')}</td><td>${money(r.amount)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">لا توجد صفوف بلا تاريخ.</td></tr>'}</tbody></table></div><div class="modal-actions"><button class="btn btn-primary" id="commit-import">اعتماد الصفوف ذات التاريخ (${valid.length})</button><button class="btn btn-light" id="export-no-date">تصدير الصفوف بلا تاريخ</button></div>`;document.getElementById('commit-import').onclick=()=>{if(!confirm(`سيتم إضافة ${valid.length} سجل تاريخي دون إنشاء مديونيات. المتشابه منها لن يُحذف. متابعة؟`))return;const existing=new Set(db.historical.map(h=>`${h.date}|${h.customerName}|${h.amount}|${h.originalNumber}`));let added=0;valid.forEach(r=>{const key=`${r.date}|${r.customerName}|${r.amount}|${r.originalNumber}`;db.historical.push({...r,id:uid('hist'),possibleDuplicate:existing.has(key)});existing.add(key);added++});audit('استيراد','بيانات تاريخية',file.name,null,{added,noDate:noDate.length,possibleDuplicates:duplicate.length});persist();notify(`تم استيراد ${added} سجل تاريخي`);render()};document.getElementById('export-no-date').onclick=()=>exportCSV(noDate.map(r=>({'التاريخ':'','العميل':r.customerName,'رقم الفاتورة الأصلي':r.originalNumber,'المبلغ':r.amount,'المصدر':r.source})),'rows-without-date.csv')}catch(e){preview.innerHTML=`<div class="notice danger-notice">تعذر قراءة الملف: ${esc(e.message)}. جرّب CSV بترميز UTF-8.</div>`}}
function loadSheetJS(){return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js';s.onload=resolve;s.onerror=()=>reject(Error('تعذر تحميل مكتبة Excel؛ استخدم CSV UTF-8'));document.head.append(s)})}
function drawSalesChart(){const canvas=document.getElementById('sales-chart');if(!canvas)return;const rect=canvas.getBoundingClientRect();const dpr=window.devicePixelRatio||1;canvas.width=Math.max(300,rect.width*dpr);canvas.height=Math.max(180,rect.height*dpr);const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const w=canvas.width/dpr,h=canvas.height/dpr;const values=Array.from({length:12},(_,i)=>monthSales(reportYear,i+1));const max=Math.max(...values,num(db.settings.monthlyDeduction),1);const pad={l:8,r:8,t:16,b:30};ctx.clearRect(0,0,w,h);ctx.font='11px Cairo, sans-serif';ctx.textAlign='center';for(let j=0;j<4;j++){const y=pad.t+(h-pad.t-pad.b)*j/3;ctx.strokeStyle='#edf1f4';ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke()}const slot=(w-pad.l-pad.r)/12;values.forEach((v,i)=>{const bh=(h-pad.t-pad.b)*v/max;const x=pad.l+i*slot+slot*.2;const y=h-pad.b-bh;ctx.fillStyle='#0f766e';ctx.beginPath();ctx.roundRect(x,y,Math.max(5,slot*.58),bh,4);ctx.fill();ctx.fillStyle='#718393';ctx.fillText(String(i+1),x+slot*.29,h-8)});const yy=h-pad.b-(h-pad.t-pad.b)*num(db.settings.monthlyDeduction)/max;ctx.strokeStyle='#f59e0b';ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(pad.l,yy);ctx.lineTo(w-pad.r,yy);ctx.stroke();ctx.setLineDash([])}
window.addEventListener('resize',()=>{if(page==='dashboard')drawSalesChart()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render()}});
function saveSupabaseConfig(){try{const url=import.meta.env.VITE_SUPABASE_URL,key=import.meta.env.VITE_SUPABASE_ANON_KEY;if(url&&key){supabase=createClient(url,key);cloudEnabled=true}}catch(e){console.warn('Supabase configuration unavailable',e)}}
saveSupabaseConfig();render();
